module div_8bit (
    input clk, rst, sign, opn_valid, res_ready,
    input [7:0] dividend, divisor,
    output res_valid,
    output [15:0] result
);
// Define states
parameter IDLE = 2'b00;
parameter LOAD = 2'b01;
parameter DIVIDE = 2'b10;
parameter DONE = 2'b11;
// Registers
reg [7:0] reg_dividend, reg_divisor;
reg [8:0] neg_divisor;
reg [17:0] sr;
reg [3:0] cnt;
reg start_cnt;
reg res_valid_reg;
// Intermediate signals
reg [9:0] sub_result;
reg [9:0] mux_out;
reg carry_in;
// Assignments
assign carry_in = ~(|sr[16:9]) & sr[8];
// Combinational logic for MUX
always @(*) begin
    case ({|sr[16:9], sr[8]})
        2'b00: mux_out = {1'b0, sr[16:9]};
        2'b01: mux_out = sub_result;
        2'b10: mux_out = {1'b1, sr[16:9]};
        2'b11: mux_out = sub_result;
    endcase
end
// Sequential logic
always @(posedge clk or posedge rst) begin
    if (rst) begin
        reg_dividend <= 8'h00;
        reg_divisor <= 8'h00;
        neg_divisor <= 9'h000;
        sr <= 18'h00000;
        cnt <= 4'h0;
        start_cnt <= 1'b0;
        res_valid_reg <= 1'b0;
    end else begin
        if (opn_valid && !res_valid_reg) begin
            reg_dividend <= dividend;
            reg_divisor <= divisor;
            neg_divisor <= ~{sign ? dividend[7] : 1'b0, divisor} + 1;
            sr <= {{8{1'b0}}, dividend, 1'b0};
            cnt <= 4'd1;
            start_cnt <= 1'b1;
        end else if (start_cnt) begin
            if (&cnt) begin
                cnt <= 4'h0;
                start_cnt <= 1'b0;
                sr <= {mux_out[8:0], sr[7:0]};
            end else begin
                cnt <= cnt + 1;
                sr <= {mux_out[8:0], sr[7:0]};
            end
        end

        if (cnt == 4'd8) begin
            res_valid_reg <= 1'b1;
        end else if (res_valid_reg && res_ready) begin
            res_valid_reg <= 1'b0;
        end
    end
end
// Output assignments
assign res_valid = res_valid_reg;
assign result = {sr[16:9], sr[7:0]};
endmodule
